from pathlib import Path
from html import escape
R=Path(__file__).parent
nav='<a href="/">Home</a><a href="/project/">Projects</a><a href="/news/">News</a><a href="/about/">About</a><a href="/contact/">Contact</a>'
languages='<div class="lang"><a href="/" lang="en">EN</a><a href="/zh-hant/" lang="zh-Hant">繁</a><a href="/zh-hans/" lang="zh-Hans">简</a><a href="/ja/" lang="ja">日</a><a href="/ko/" lang="ko">한</a></div>'
def page(title,description,content,filename):
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Aurora Studio</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="https://www.aurora-studio.org/{filename.replace('index.html','')}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a href="/" class="brand" aria-label="Aurora Studio home"><span class="brand-icon">A<span>✦</span></span><span>AURORA<br><small>STUDIO</small></span></a><nav aria-label="Main navigation">{nav}</nav>{languages}<a class="header-contact" href="mailto:press@aurora-studio.org">Get in touch <span aria-hidden="true">↗</span></a></header><main id="main">{content}</main><footer><div><strong>AURORA STUDIO</strong><p>Independent game development · Hong Kong</p></div><div><a href="/project/">Projects</a><a href="/news/">News</a><a href="/contact/">Contact</a></div><small>© 2026 Aurora Studio</small></footer></body></html>'''
 p=R/filename;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html)
page('Independent games from Hong Kong','Aurora Studio creates simulation and narrative experiences inspired by Asia.','''<section class="hero"><div class="hero-image" role="img" aria-label="Two buses in the Project Numazu game environment"></div><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">INDEPENDENT GAME STUDIO · HONG KONG</p><h1>Places worth<br><em>getting lost in.</em></h1><p>We build simulation and narrative worlds shaped by the details, stories and streets of East Asia.</p><div class="actions"><a class="button light" href="/project/">Explore our projects <span aria-hidden="true">↗</span></a><a class="text-link" href="/about/">Meet the studio <span aria-hidden="true">→</span></a></div></div><div class="hero-caption">01 / OMSI 2 ADD-ON: PROJECT NUMAZU</div></section><section class="section intro"><div><p class="eyebrow dark">WHAT WE MAKE</p><h2>Built with a sense<br>of place.</h2></div><p>From a bus journey through Shizuoka to a supernatural pilgrimage across Edo-period Japan, we make worlds that reward curiosity and attention.</p></section><section class="section projects"><div class="section-head"><p class="eyebrow dark">SELECTED WORK</p><a href="/project/">All projects ↗</a></div><div class="project-grid"><a class="feature-card" href="/project/project-numazu/"><img src="/assets/numazu-route.jpg" alt="Bus travelling through a Project Numazu street" loading="lazy"><div><span>SIMULATION · RELEASED</span><h3>Project Numazu</h3><p>A carefully reconstructed Japanese city for OMSI 2.</p><b aria-hidden="true">↗</b></div></a><a class="type-card" href="https://revenant-tsushima.aurora-studio.org/"><span>NARRATIVE HORROR · IN DEVELOPMENT</span><div class="symbol" aria-hidden="true">津</div><h3>Revenant of Tsushima</h3><p>An Edo-era folk horror journey through memory, ritual and the supernatural.</p><b aria-hidden="true">↗</b></a></div></section><section class="callout"><p class="eyebrow">LET'S CONNECT</p><h2>Have a story to tell<br>or a world to build?</h2><a class="button light" href="/contact/">Contact the studio ↗</a></section>''','index.html')
page('Projects','Explore Project Numazu, Revenant of Tsushima, Railway Depot and Aurora Engine.','''<section class="page-heading"><p class="eyebrow dark">OUR WORK</p><h1>Projects<span class="dot">.</span></h1><p>Simulated places, lived-in systems and stories from East Asia.</p></section><section class="section project-list"><article class="listing"><img src="/assets/numazu-buses.jpg" alt="Two buses in Project Numazu"><div><span class="eyebrow dark">01 / SIMULATION · RELEASED</span><h2>OMSI 2: Project Numazu</h2><p>Drive through a 1:1 scale recreation of Numazu, Shizuoka, from its station district to the coastal landmarks and everyday streets around it.</p><a href="/project/project-numazu/">Explore Project Numazu ↗</a></div></article><article class="listing alt"><div class="art-tile">津</div><div><span class="eyebrow dark">02 / FOLK HORROR · IN DEVELOPMENT</span><h2>Revenant of Tsushima</h2><p>A first-person journey through an Edo-period Japan reshaped by the awakening of Tsushima Mewa, a shrine maiden sealed for more than three centuries.</p><a href="https://revenant-tsushima.aurora-studio.org/">Visit official project site ↗</a></div></article><article class="mini-list"><span>03 / MANAGEMENT SIMULATION</span><h2>Railway Depot: Operations &amp; Empire</h2><p>Run the railway behind the trains: depot operations, maintenance and dispatch.</p><a href="https://shikosama.itch.io/railway-depot">See the pre-alpha ↗</a></article><article class="mini-list"><span>04 / TECHNOLOGY</span><h2>Aurora Engine</h2><p>A modular C++ and Unreal framework for NPC perception, memory and decisions.</p><a href="https://github.com/Shiko215/aurora-engine">View the project ↗</a></article></section>''','project/index.html')
page('Project Numazu','Explore the Numazu, Shizuoka recreation for OMSI 2.','''<section class="project-hero"><img src="/assets/numazu-buses.jpg" alt="Japanese buses in the Project Numazu game environment"><div><p class="eyebrow">OMSI 2 ADD-ON · AVAILABLE ON STEAM</p><h1>Project<br>Numazu.</h1><p>A journey into the streets and coastal scenery of Numazu, Shizuoka.</p><a class="button light" href="https://store.steampowered.com/app/3880120/">View on Steam ↗</a></div></section><section class="section prose"><p class="eyebrow dark">THE PROJECT</p><h2>Japan, one route at a time.</h2><p>Project Numazu brings the city’s urban core, bus routes and coastal atmosphere into OMSI 2. The team recreated familiar landmarks, streets and transit details to give players a place that feels grounded in everyday life.</p><p>Developed by Aurora Studio with collaborators including Negi-Kyu Workshop. Released March 2026.</p><a href="/project/">← All projects</a></section>''','project/project-numazu/index.html')
page('About','Aurora Studio is an independent game development team based in Hong Kong.','''<section class="page-heading"><p class="eyebrow dark">ABOUT THE STUDIO</p><h1>Made in Hong Kong.<br><em>Inspired by Asia.</em></h1><p>Aurora Studio is an independent game development team based in Hong Kong.</p></section><section class="section two-column"><h2>Who we are</h2><div><p>We craft simulation and narrative-driven experiences inspired by Asia, combining cultural detail with technical precision.</p><p>Founded by Shiko Leung, the studio works with creators and partners across disciplines to bring local places and original stories to a global audience.</p><h3>Shiko Leung</h3><p>Founder &amp; Creative Director<br>Game direction, environment design, production and studio operations.</p></div></section><section class="callout"><p class="eyebrow">WORK WITH US</p><h2>Let's make something<br>memorable.</h2><a class="button light" href="/contact/">Contact the studio ↗</a></section>''','about/index.html')
page('News','Updates from Aurora Studio and its game projects.','''<section class="page-heading"><p class="eyebrow dark">FROM THE STUDIO</p><h1>News<span class="dot">.</span></h1><p>Selected announcements and milestones. Earlier articles are being restored from the previous website.</p></section><section class="section news-list"><article><time datetime="2026-09-17">17 SEP 2026</time><div><span>PROJECT UPDATE</span><h2>A Day in the Depot: Railway Depot: Operations &amp; Empire</h2><p>Introducing a management simulation about the work that keeps a railway running.</p><a href="https://shikosama.itch.io/railway-depot">Visit the project ↗</a></div></article><article><time datetime="2026-03-30">30 MAR 2026</time><div><span>RELEASE</span><h2>Project Numazu is available on Steam</h2><p>Aurora Studio’s recreation of Numazu for OMSI 2 has launched.</p><a href="/project/project-numazu/">Explore the game ↗</a></div></article><article><time datetime="2025-12-01">01 DEC 2025</time><div><span>PROJECT UPDATE</span><h2>Project Numazu Steam page goes live</h2><p>The public store page introduced the team’s Japanese city simulation to players.</p><a href="https://store.steampowered.com/app/3880120/">View on Steam ↗</a></div></article></section>''','news/index.html')
page('Contact','Get in touch with Aurora Studio for press, partnerships and project enquiries.','''<section class="page-heading"><p class="eyebrow dark">CONTACT</p><h1>Let's talk<span class="dot">.</span></h1><p>For coverage, partnerships or a conversation about our work, write to the studio directly.</p></section><section class="section contact-grid"><a href="mailto:press@aurora-studio.org"><span>PRESS &amp; PARTNERSHIPS</span><h2>press@aurora-studio.org</h2><b>↗</b></a><a href="mailto:support@aurora-studio.org"><span>PLAYER SUPPORT</span><h2>support@aurora-studio.org</h2><b>↗</b></a></section>''','contact/index.html')
